window.B0B_INTRO_CHAPTERS=[{"id": "I", "title": "The charter", "year": "1874", "at": 0.0, "end": 25.065, "map": false, "lines": [{"text": "London, the last day of 1600. A queen signs a charter, and a company is born that will outlive her by two hundred and seventy years.", "at": 0.35, "end": 8.789}, {"text": "In time it won the right to make war, coin money and hold courts. When the Crown took it over in 1858, its armies became the Queen's, and its offices carried on as the Raj.", "at": 9.239, "end": 20.128}, {"text": "Build something that is not a person, and it does not have to die.", "at": 20.578, "end": 24.366}]}, {"id": "II", "title": "The bank", "year": "2026", "at": 25.065, "end": 48.721, "map": false, "lines": [{"text": "Basel, 1930. A bank for central banks opens to settle German reparations. The reparations ended in 1932. The bank did not.", "at": 25.415, "end": 34.781}, {"text": "At Bretton Woods in 1944 the Allies recommended its liquidation at the earliest possible moment. By 1948 the recommendation had been put aside.", "at": 35.231, "end": 45.067}, {"text": "Today sixty-three central banks are members.", "at": 45.517, "end": 48.023}]}, {"id": "III", "title": "The relocation plan", "year": "2016", "at": 48.721, "end": 74.627, "map": false, "lines": [{"text": "Continuity of government is not a rumour. It is a line of directives, each signed to replace the last, from Eisenhower to now, under both parties.", "at": 49.071, "end": 57.508}, {"text": "Mountains were hollowed out for it. A bunker for the whole of Congress sat under a resort hotel for three decades, until a newspaper found it.", "at": 57.958, "end": 65.932}, {"text": "It was switched on once: the eleventh of September, 2001. The text of the directive in force today has not been released.", "at": 66.382, "end": 73.928}]}, {"id": "IV", "title": "The emergency", "year": "2026", "at": 74.627, "end": 94.502, "map": false, "lines": [{"text": "Three days later a national emergency was declared. Every president since has renewed it.", "at": 74.977, "end": 79.659}, {"text": "Congress authorised force in a single sentence, naming no country and setting no end date. The two Iraq authorisations were repealed in December 2025. That one was not.", "at": 80.109, "end": 90.718}, {"text": "The attack ended. The instruments did not.", "at": 91.168, "end": 93.803}]}, {"id": "V", "title": "The door", "year": "2025", "at": 94.502, "end": 121.991, "map": false, "lines": [{"text": "Eisenhower, leaving office in 1961: in the councils of government, we must guard against the acquisition of unwarranted influence, whether sought or unsought, by the military-industrial complex.", "at": 94.852, "end": 106.911}, {"text": "Paul Volcker went from Chase Manhattan to the Treasury, back to Chase, back to the Treasury, and then to the chair of the Federal Reserve.", "at": 107.361, "end": 115.063}, {"text": "The people rotate. The desks do not. It is less a revolving door than one room with many desks.", "at": 115.513, "end": 121.292}]}, {"id": "VI", "title": "The contractor", "year": "2024", "at": 121.991, "end": 150.03, "map": false, "lines": [{"text": "Lockheed is older than the CIA. It built the Agency's U-2 in 1955, and the A-12 after it.", "at": 122.341, "end": 129.086}, {"text": "In 1976 its foreign payments reached a prince. Bernhard of the Netherlands, who had chaired the Bilderberg meetings since 1954, gave up his military posts and the chair. The next year, bribing foreign officials became a federal crime.", "at": 129.536, "end": 143.963}, {"text": "Today it is the world's largest arms producer. The scandal ended. The contracts did not.", "at": 144.413, "end": 149.331}]}, {"id": "VII", "title": "The clock", "year": "2026", "at": 150.03, "end": 175.919, "map": false, "lines": [{"text": "MKUltra: authorised 1953, exposed in the seventies. Northwoods: written 1962, released 1997. The UKUSA agreement: signed 1946, released 2010.", "at": 150.38, "end": 164.093}, {"text": "The money moves on less paper still. Since 1949, the Director's certificate has been the voucher.", "at": 164.543, "end": 170.547}, {"text": "The clock says when a record surfaces. It does not say what the record will say.", "at": 170.997, "end": 175.219}]}, {"id": "VIII", "title": "The empty seat", "year": "2026", "at": 175.919, "end": 196.543, "map": false, "lines": [{"text": "Climb the pyramid and the names thin out into rules: asset managers, central banks, sovereign funds. Vanguard is owned by its own funds.", "at": 176.269, "end": 185.114}, {"text": "The seat at the top is real, load-bearing and empty. Hand it a family or a bloodline and the analysis is over. That is the oldest way this research goes bad.", "at": 185.564, "end": 195.845}]}, {"id": "IX", "title": "The pattern points", "year": "2026", "at": 196.543, "end": 210.27, "map": false, "lines": [{"text": "These are the pattern points, and they correlate.", "at": 201.343, "end": 203.884}, {"text": "A shared timeline is not a chain.", "at": 204.334, "end": 206.67}]}];
window.B0B_INTRO_REEL_DUR=210.27;
